static int api_dget(lua_State *L)
{
  int i = p8a_int(L, 1);
  if (i >= 0 && i < 64) {
    unsigned int a = P8_PERSIST + (unsigned int)i * 4;
    uint32_t v = (uint32_t)p8_ram[a] | ((uint32_t)p8_ram[a + 1] << 8) |
                 ((uint32_t)p8_ram[a + 2] << 16) |
                 ((uint32_t)p8_ram[a + 3] << 24);
    lua_pushnumber(L, (lua_Number)(long)(int32_t)v);
  } else {
    lua_pushnumber(L, 0);
  }
  return 1;
}

static int api_dset(lua_State *L)
{
  int i = p8a_int(L, 1);
  if (i >= 0 && i < 64) {
    unsigned int a = P8_PERSIST + (unsigned int)i * 4;
    uint32_t v = (uint32_t)(long)lua_tonumber(L, 2);
    p8_ram[a] = (uint8_t)(v & 0xFF);
    p8_ram[a + 1] = (uint8_t)((v >> 8) & 0xFF);
    p8_ram[a + 2] = (uint8_t)((v >> 16) & 0xFF);
    p8_ram[a + 3] = (uint8_t)((v >> 24) & 0xFF);
  }
  return 0;
}

static int api_stat(lua_State *L)
{
  (void)p8a_optint(L, 1, 0); /* VERIFY: everything reports 0 for now */
  lua_pushnumber(L, 0);
  return 1;
}

